class HashMap {
  constructor(initialCapacity=16,loadFactor=0.75){this.capacity=initialCapacity;this.loadFactor=loadFactor;this.size=0;this.buckets=Array.from({length:this.capacity},()=>[]);}
  _hash(key){let hash=0;for(const c of String(key))hash=(hash*31+c.charCodeAt(0))%this.capacity;return hash;}
  set(key,value){const idx=this._hash(key);const bucket=this.buckets[idx];for(const pair of bucket){if(pair[0]===key){pair[1]=value;return;}}bucket.push([key,value]);this.size++;if(this.size/this.capacity>this.loadFactor)this._rehash();}
  get(key){const bucket=this.buckets[this._hash(key)];for(const[k,v]of bucket)if(k===key)return v;return undefined;}
  _rehash(){const oldBuckets=this.buckets;this.capacity*=2;this.buckets=Array.from({length:this.capacity},()=>[]);this.size=0;for(const bucket of oldBuckets)for(const[k,v]of bucket)this.set(k,v);}
}
function hashJoinImpl(tableA,tableB,keyA,keyB){const ht=new Map();for(const rowA of tableA){const k=rowA[keyA];if(!ht.has(k))ht.set(k,[]);ht.get(k).push(rowA);}const result=[];for(const rowB of tableB){const matches=ht.get(rowB[keyB])||[];for(const rowA of matches)result.push({...rowA,...rowB});}return result;}

