class ConsistentHash {
  constructor(virtualNodes=150){this.virtualNodes=virtualNodes;this.ring=[];this.nodeMap=new Map();}
  _hash(key){let h=0;for(const c of String(key))h=(h*31+c.charCodeAt(0))>>>0;return h;}
  addNode(node){const positions=[];for(let i=0;i<this.virtualNodes;i++){const hash=this._hash(`${node}:vnode:${i}`);positions.push(hash);this.ring.push({hash,node});}this.ring.sort((a,b)=>a.hash-b.hash);this.nodeMap.set(node,positions);}
  removeNode(node){const positions=new Set(this.nodeMap.get(node)||[]);this.ring=this.ring.filter(e=>!positions.has(e.hash));this.nodeMap.delete(node);}
  getNode(key){if(!this.ring.length)return null;const hash=this._hash(key);let lo=0,hi=this.ring.length;while(lo<hi){const mid=(lo+hi)>>1;if(this.ring[mid].hash<hash)lo=mid+1;else hi=mid;}const idx=lo%this.ring.length;return this.ring[idx].node;}
}

