class BloomFilter {
  constructor(m,k){this.m=m;this.k=k;this.bits=new Uint8Array(Math.ceil(m/8));}
  _hashes(key){const s=String(key);let h1=0,h2=0;for(const c of s){h1=(h1*31+c.charCodeAt(0))>>>0;h2=(h2*37+c.charCodeAt(0))>>>0;}const positions=[];for(let i=0;i<this.k;i++)positions.push(((h1+i*h2)>>>0)%this.m);return positions;}
  _getBit(pos){return(this.bits[pos>>3]>>(pos&7))&1;}
  _setBit(pos){this.bits[pos>>3]|=1<<(pos&7);}
  add(key){for(const pos of this._hashes(key))this._setBit(pos);}
  mightContain(key){return this._hashes(key).every(pos=>this._getBit(pos)===1);}
  static optimalParams(n,p){const m=Math.ceil(-n*Math.log(p)/(Math.LN2**2));const k=Math.round((m/n)*Math.LN2);return{m,k,expectedFPRate:(1-Math.exp(-k*n/m))**k};}
}

class LRUCache {
  constructor(capacity){this.capacity=capacity;this.map=new Map();this.head={key:null,val:null,prev:null,next:null};this.tail={key:null,val:null,prev:null,next:null};this.head.next=this.tail;this.tail.prev=this.head;}
  _remove(node){node.prev.next=node.next;node.next.prev=node.prev;}
  _insertFront(node){node.next=this.head.next;node.prev=this.head;this.head.next.prev=node;this.head.next=node;}
  get(key){if(!this.map.has(key))return-1;const node=this.map.get(key);this._remove(node);this._insertFront(node);return node.val;}
  put(key,value){if(this.map.has(key)){const node=this.map.get(key);node.val=value;this._remove(node);this._insertFront(node);}else{if(this.map.size===this.capacity){const lru=this.tail.prev;this._remove(lru);this.map.delete(lru.key);}const node={key,val:value,prev:null,next:null};this._insertFront(node);this.map.set(key,node);}}
}
class LFUCache {
  constructor(capacity){this.capacity=capacity;this.keyMap=new Map();this.freqMap=new Map();this.minFreq=0;}
  _getOrCreate(freq){if(!this.freqMap.has(freq))this.freqMap.set(freq,new Map());return this.freqMap.get(freq);}
  _touch(key){const{val,freq}=this.keyMap.get(key);this.freqMap.get(freq).delete(key);if(freq===this.minFreq&&this.freqMap.get(freq).size===0)this.minFreq++;const newFreq=freq+1;this.keyMap.set(key,{val,freq:newFreq});this._getOrCreate(newFreq).set(key,true);}
  get(key){if(!this.keyMap.has(key))return-1;this._touch(key);return this.keyMap.get(key).val;}
  put(key,value){if(this.capacity<=0)return;if(this.keyMap.has(key)){this.keyMap.get(key).val=value;this._touch(key);return;}if(this.keyMap.size===this.capacity){const evictKey=this.freqMap.get(this.minFreq).keys().next().value;this.freqMap.get(this.minFreq).delete(evictKey);this.keyMap.delete(evictKey);}this.keyMap.set(key,{val:value,freq:1});this._getOrCreate(1).set(key,true);this.minFreq=1;}
}

